import * as Material from "@mui/material";
export function Subject({ compact }: { compact: boolean }) {
  return <Material.Button sx={[{ mt: { xs: 1, md: 3 } }, compact ? { width: 160 } : { display: "inline-flex" }]}>Continue</Material.Button>;
}

import Button from "@mui/material/Button";
export function Subject() {
  return <Button sx={{ "&:focus-visible": { py: { xs: 1, md: 2 } } }}>Continue</Button>;
}

import { DataGrid as Records } from "@mui/x-data-grid";
export function Subject() {
  return <Records rows={[]} columns={[]} sx={{ width: { xs: "100%", md: 640 }, "@media print": { display: "block" } }} />;
}

import { DataGrid as Records } from "@mui/x-data-grid";
export function Subject() {
  return <Records rows={[]} columns={[]} sx={{ svg: { stroke: "hsl(calc(240) 100% 50%)" } }} />;
}

import { DatePicker } from "@mui/x-date-pickers/DatePicker";
export function Subject() {
  return <DatePicker sx={[false, { my: { xs: 1, lg: 2 }, height: 56 }]} slotProps={{ textField: { required: true } }} />;
}

import { TimePicker } from "@mui/x-date-pickers";
export function Subject() {
  return <TimePicker sx={{ "&:focus-within": { borderColor: "var(--brand, #123456)" } }} />;
}

import { LineChart as Trends } from "@mui/x-charts/LineChart";
const placement = { m: 1, width: "100%" } as const;
export function Subject() {
  return <Trends series={[{ data: [2, 5] }]} sx={{ ...placement, height: 220 }} />;
}

import { LineChart as Trends } from "@mui/x-charts";
export function Subject() {
  return <Trends series={[{ data: [2, 5] }]} sx={{ "& > svg path": { stroke: "color-mix(in srgb, var(--mui-palette-primary-main) 60%, rebeccapurple)" } }} />;
}

import { SimpleTreeView } from "@mui/x-tree-view";
import { TreeItem } from "@mui/x-tree-view/TreeItem";
export function Subject() {
  return <SimpleTreeView sx={{ width: 280 }}><TreeItem itemId="root" label="Root" sx={{ mt: { xs: 1, md: 2 } }} /></SimpleTreeView>;
}

import { RichTreeView as Explorer } from "@mui/x-tree-view/RichTreeView";
export function Subject() {
  return <Explorer items={[{ id: "root", label: "Root" }]} sx={{ color: { xs: "text.primary", md: "rgb(calc(0) calc(0) calc(0))" } }} />;
}
